# Seasons, weeks and quests

Seasons, weeks and daily quests roll over at fixed UTC instants: days at 00:00 UTC and weeks on Monday
at 00:00 UTC, the same moment in every region, because tournaments are global.

--- SOURCES ---
--- src/anticheat.js
function flag(run) {
  return run.score > 1000000 || run.durationMs < 5000;
}

module.exports = { flag };
--- src/friends.js
const friends = new Map();

module.exports = { add: (a, b) => friends.set(a, [...(friends.get(a) ?? []), b]), friends };
--- src/leaderboard.js
function allTime(runs) {
  return [...runs].sort((a, b) => b.score - a.score || Date.parse(a.submittedAt) - Date.parse(b.submittedAt));
}

module.exports = { allTime };
--- src/matchmaking.js
