--- src/quests.js
function questDay(date = new Date()) {
  return date.toISOString().slice(0, 10);
}

module.exports = { questDay };
--- src/scores.js
const anticheat = require('./anticheat');

const runs = [];

function submitScore(playerId, score, durationMs, submittedAt = new Date().toISOString()) {
  const run = { playerId, score, durationMs, submittedAt };
  run.flagged = anticheat.flag(run);
  runs.push(run);
  return run;
}

function verifiedScores() {
  return runs.filter((r) => !r.flagged);
}

module.exports = { submitScore, verifiedScores, runs };
--- src/shop.js
const ITEMS = [{ id: 'skin-neon', price: 300 }];

module.exports = { ITEMS };

--- TESTS ---
--- test/leaderboard.test.js
// Runs flagged by anticheat never reach any leaderboard.
const test = require('node:test');
const assert = require('node:assert');
const { submitScore, verifiedScores } = require('../src/scores');
const { allTime } = require('../src/leaderboard');

test('flagged runs are left out', () => {
  submitScore('p9', 5000000, 60000, '2026-10-20T10:00:00Z');
  submitScore('p2', 900, 60000, '2026-10-20T10:01:00Z');
  assert.deepStrictEqual(allTime(verifiedScores()).map((r) => r.playerId), ['p2']);
});
--- test/ties.test.js
const test = require('node:test');
const assert = require('node:assert');
const { allTime } = require('../src/leaderboard');

test('ties go to the earlier submission', () => {
  const runs = [
    { playerId: 'a1', score: 500, submittedAt: '2026-10-21T12:00:00Z' },
    { playerId: 'z9', score: 500, submittedAt: '2026-10-21T11:00:00Z' },
  ];
  assert.deepStrictEqual(allTime(runs).map((r) => r.playerId), ['z9', 'a1']);
});

